            if (!toast) {
                break;
            }
            try {
                const result = await client.tui.showToast({
                    body: {
                        title: "Tailscale Aperture",
                        message: toast.message,
                        variant: toast.variant,
                        duration: 10_000,
                    },
                    query: {
                        directory: input.directory,
                    },
